	async initByFile(fileContent, fileName, scale = 0.0001) {
        const extension = fileName.split('.').pop().toLowerCase();
        
        switch (extension) {
            case 'obj':
                return this.initByOBJ(fileContent, scale);
            case 'fbx':
                // FBX는 일반적으로 바이너리 파일이므로 URL이나 File 객체가 필요
                if (typeof fileContent === 'string' && fileContent.startsWith('http')) {
                    return await this.initByFBX(fileContent, scale);
                } else {
                    throw new Error('FBX 파일은 URL 또는 File 객체가 필요합니다.');
                }
            default:
                throw new Error(`지원하지 않는 파일 형식: ${extension}`);
        }
    }

